async Task ImportAsync(string[] files, CancellationToken ct)
{
    foreach (var f in files)
    {
        ct.ThrowIfCancellationRequested();              // проверка между файлами
        var text = await File.ReadAllTextAsync(f, ct); // и передача вглубь
        Parse(text);                                    // синхронная работа
    }
}
